'use strict';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={offline:false,savedBoards:[],me:null,overview:null,samples:[],board:null,route:'dashboard',search:'',category:'Todos',busy:false,accounts:[],libraryAdmin:[],contributions:[],pendingContributions:[],shared:null,community:[]};
const adminNotices=createAdminNotifications({getClient:async()=>(await getBackend()).client});
let notificationState={status:'loading'},notificationBusy=false,notificationVersion=0,accountDeletionBusy=false;
const active=new Map();let preview=null,toastTimer=null,modalHandler=null,lastFocus=null;
const audioLevels=createAudioLevels({master:Number($('#master-volume').value)/100});
const eventFader=createEventFader({active,stop:removePlayingTrack,levels:audioLevels,pause:id=>pauseTracks(active,[id]),onChange:()=>updateTransport()});
const usesEventFader=()=>document.body.classList.contains('event-mode')&&state.board?.playlist.event_fade_enabled!==false;
const playlistBatches=new Map();let playlistBatchBusy=false,deviceSessionVersion=0;
const eventWake=createEventWakeLock({onChange:status=>updateWakeStatus(status)});
function updateWakeStatus(status){const label=$('#event-screen-status');if(!label)return;label.hidden=!document.body.classList.contains('event-mode');label.textContent=status==='held'?'Tela ativa':status==='requesting'?'Ativando tela…':'Tela pode apagar'}
function endSessionWork(){deviceAudio.clear();deviceSessionVersion++;void eventWake.setActive(false);document.body.classList.remove('event-mode');for(const job of playlistBatches.values())job.cancelled=true}
const deviceAudio=createDeviceAudioCache({audio:offlineAudio,isCurrent:owner=>state.me?.profile.id===owner&&state.me?.access.status==='approved',onStorageError:error=>toast(error?.name==='QuotaExceededError'?'Sem espaço no dispositivo. O áudio será reproduzido sem salvar.':'Não foi possível salvar neste dispositivo. O áudio será reproduzido.',true)});
const cacheId=track=>track.sample_id?'@library:'+track.sample_id:track.id;
async function rememberHeardPlaylist(board,me,sessionVersion){if(deviceSessionVersion!==sessionVersion||state.me?.profile.id!==me.profile.id)return;try{if(!board.tracks.length)return;for(const track of board.tracks)if(!await offlineAudio.has(me.profile.id,track.id))return;if(deviceSessionVersion!==sessionVersion)return;await offlinePlaylists.save(me,board);if(deviceSessionVersion!==sessionVersion)return;await offlinePlaylists.setOrder(me.profile.id,state.overview?.playlists||[]);state.savedBoards=await offlinePlaylists.boards(me.profile.id)}catch{}}
let audioPlan='',audioPlanVersion=0;
const preparedAudio=createAudioPool({makeAudio:()=>{const audio=new Audio();audio.crossOrigin='anonymous';return audio},isRetained:audio=>[...active.values()].some(item=>item.audio===audio),loadLocal:item=>offlineAudio.load(state.me.profile.id,item.id),onChange:()=>updateReadiness()});
function updateReadiness(){const stats=preparedAudio.stats();const label=$('#audio-ready');if(label)label.textContent=stats.ready?(stats.ready===stats.total?'Áudios prontos':`${stats.ready}/${stats.total} faixas prontas`):'';for(const button of document.querySelectorAll('[data-action="play"],[data-action="preview"]')){const entry=preparedAudio.get(button.dataset.id);button.dataset.ready=entry?.state==='ready'?'true':'false'}}
function clearPreparedAudio(){audioPlan='';audioPlanVersion++;preparedAudio.clear()}
function primeAudio(){const tracks=state.board?.tracks;const list=tracks||(['library','admin-library'].includes(state.route)?state.samples:null);if(!list){if(audioPlan&&!active.size)clearPreparedAudio();return}const key=(tracks?'playlist:':'library:')+list.map(t=>[t.id,t.audio_path,t.sample_id,t.url].join(':')).join('|');if(key===audioPlan)return;audioPlan=key;++audioPlanVersion;
if(tracks&&state.offline){preparedAudio.prepare(tracks.map(t=>({id:t.id,url:'offline:'+state.me.profile.id+':'+t.id,size:t.file_size||0,localOnly:true})));return}
if(!tracks){preparedAudio.prepare([]);return}
preparedAudio.prepare(tracks.map(t=>({id:t.id,url:'device:'+state.me.profile.id+':'+cacheId(t),size:t.file_size||0})));}
const sampleAudio=$('#sample-audio');
const samplePreview=createPreviewPlayer(sampleAudio,status=>{
preview=status?{id:status.id,audio:sampleAudio,name:status.title,playing:status.state==='playing'}:null;
$('#sample-preview').hidden=!status;document.body.classList.toggle('preview-open',!!status);
if(status){$('#preview-title').textContent=status.title;$('#preview-status').textContent=previewMessage(status.state)}
updatePreviewButtons();updateTransport();
});
$('#preview-close').onclick=()=>stopPreview();
let previewURL=null,previewLoadVersion=0;
function stopPreview(){previewLoadVersion++;samplePreview.stop();if(previewURL){URL.revokeObjectURL(previewURL);previewURL=null}}
function updatePreviewButtons(){for(const b of document.querySelectorAll('[data-action="preview"]')){const selected=preview?.id===b.dataset.id,playing=selected&&!sampleAudio.paused&&!sampleAudio.ended;b.setAttribute('aria-pressed',String(playing));b.textContent=selected&&samplePreview.current?.state==='loading'?'Carregando…':playing?'■ Parar':'▶ Ouvir'}}
const bytes=x=>x>=1024*1024*1024?(x/(1024*1024*1024)).toFixed(1)+' GB':x<1024*1024?(x/1024).toFixed(0)+' KB':(x/1024/1024).toFixed(1)+' MB';
function toast(message,error=false){if(error)globalThis.harmonyReportError?.('operation',new Error());clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.toggle('error',error);$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,error?9000:4500)}
async function api(path,options={}){
 if(state.offline)return offlinePlaylists.call(path,options);
 try{const value=await(await getBackend()).call(path,options);if(path==='/overview'&&state.me&&value.limits)state.me.limits=accountLimits(value.limits);if(path==='/overview'&&state.me){await offlinePlaylists.setOrder(state.me.profile.id,value.playlists).catch(()=>{});state.savedBoards=await offlinePlaylists.boards(state.me.profile.id).catch(()=>[])}if(path==='/access'&&value.status!=='approved'||path==='/me'&&value.access.status!=='approved')await revokeDownloads();
 if((options.method||'GET')==='GET'&&/^\/playlists\/[^/]+$/.test(path)&&state.me){await offlinePlaylists.sync(state.me,value).catch(()=>{});state.savedBoards=await offlinePlaylists.boards(state.me.profile.id).catch(()=>[])}
 if(options.method==='DELETE'&&/^\/playlists\/[^/]+$/.test(path)){await offlinePlaylists.remove(state.me.profile.id,path.split('/')[2]);state.savedBoards=await offlinePlaylists.boards(state.me.profile.id)}return value;
 }catch(e){if(e.status===401){await revokeDownloads();endSessionWork();stopAll();location.assign('login.html')}throw e}
}
async function revokeDownloads(){deviceAudio.clear();const id=state.me?.profile.id||offlinePlaylists.owner();offlinePlaylists.forget();if(id)await offlinePlaylists.clear(id).catch(()=>{});state.savedBoards=[]}
async function enterOffline(preservePlayback=false){const data=await offlinePlaylists.restore();if(!data?.boards.length)return false;if(!preservePlayback){endSessionWork();stopAll();clearPreparedAudio()}state.offline=true;state.me=data.me;state.savedBoards=data.boards;state.samples=[];updateAccount();return true}
function offlineUI(){document.body.classList.toggle('offline-mode',state.offline);$('#offline-banner').hidden=!state.offline;for(const a of document.querySelectorAll('[data-nav]'))if(!['dashboard','playlists','downloads'].includes(a.dataset.nav))a.hidden=state.offline||(['admin','admin-library'].includes(a.dataset.nav)&&!state.me.access.is_admin);if(state.offline){for(const b of document.querySelectorAll('#view button[data-action],#view .pad-drag'))if(!['play','event-mode','clear-device','retry','reconnect','signout'].includes(b.dataset.action))b.disabled=true;for(const a of document.querySelectorAll('#view a'))if(!/app.html#(?:playlists|studio\/|downloads)/.test(a.getAttribute('href')||''))a.hidden=true}}
let watchingAuth=false;
async function onlineBackend(){const backend=await getBackend();if(!watchingAuth){watchingAuth=true;backend.client.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){void revokeDownloads();endSessionWork();void adminNotices.localUnsubscribe();stopAll();clearPreparedAudio();location.replace('login.html')}else if(event==='SIGNED_IN'&&state.me&&session?.user?.id!==state.me.profile.id){void revokeDownloads();endSessionWork();stopAll();clearPreparedAudio();location.reload()}})}return backend}
async function verifyReconnection(){if(!state.offline||navigator.onLine===false)return;try{const backend=await onlineBackend(),me=await backend.call('/me');if(me.profile.id!==state.me.profile.id||me.access.status!=='approved'){await revokeDownloads();endSessionWork();stopAll();clearPreparedAudio();location.replace('login.html');return}const overview=await backend.call('/overview');state.me=me;state.overview=overview;state.offline=false;updateAccount();render();toast('Conexão restabelecida.')}catch(error){if([400,401,403].includes(Number(error.status))){await revokeDownloads();endSessionWork();stopAll();clearPreparedAudio();location.replace('login.html')}}}
async function reconnect(){if(navigator.onLine===false){toast('Você ainda está sem conexão.');return}try{const backend=await getBackend(),me=await backend.call('/me');if(me.profile.id!==state.me.profile.id||me.access.status!=='approved'){await revokeDownloads();location.replace('login.html');return}location.reload()}catch(error){if([400,401,403].includes(error.status)){await revokeDownloads();location.replace('login.html');return}toast('Não foi possível conectar. Suas playlists baixadas continuam disponíveis.',true)}}
async function signout(){endSessionWork();stopAll();clearPreparedAudio();await revokeDownloads();if(state.offline){localStorage.removeItem('soundbar-supabase-session');localStorage.removeItem('soundbar-supabase-session-code-verifier');location.replace('login.html');return}await adminNotices.disable().catch(()=>adminNotices.localUnsubscribe());await(await getBackend()).client.auth.signOut();location.replace('login.html')}

function wave(seed=0){return '<div class="playlist-art">'+[20,36,48,30,58,40,26,44,32,17].map((h,i)=>`<i style="height:${Math.max(10,h-(seed%3)*4)}px"></i>`).join('')+'</div>'}
function header(title,description,actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="actions">${actions}</div></div>`}
const newButton='<button class="btn primary" data-action="new-playlist">＋ Nova playlist</button>';
function card(p,i){const reorder=!state.offline&&state.me?.access.status==='approved';return `<article class="playlist-tile" data-playlist-id="${esc(p.id)}"><a class="playlist-card" draggable="false" href="app.html#studio/${encodeURIComponent(p.id)}" style="${playlistColorStyle(p.color)}">${wave(i)}<h3>${esc(p.name)}</h3><p>${esc(p.description||'Uma nova seleção de momentos.')}</p><div class="card-bottom"><span>${p.tracks_count||0} faixas · ${p.play_mode==='single'?'uma por vez':'mix livre'}</span><span>↗</span></div></a>${reorder?`<button type="button" class="playlist-drag" aria-label="Reordenar ${esc(p.name)}: segure e arraste ou use as setas do teclado" aria-pressed="false" title="Segure e arraste para mudar a ordem" ${movingPlaylists?'disabled':''}>⠿</button>`:''}</article>`}

function emptyPlaylists(){return `<div class="empty-state"><div class="empty-icon">≋</div><h2>Sua primeira playlist está esperando.</h2><p>Crie uma playlist, escolha um nome e adicione áudios do seu dispositivo ou da biblioteca.</p>${newButton}</div>`}
function dashboard(){const o=state.overview;return header('Olá, '+state.me.profile.display_name.split(' ')[0]+'.','Seu próximo momento começa aqui.',newButton)+`<section class="stats" aria-label="Resumo do estúdio"><div class="stat"><span class="caption">PLAYLISTS</span><strong>${o.playlists.length}</strong><small>Momentos organizados</small></div><div class="stat"><span class="caption">FAIXAS</span><strong>${o.tracks}</strong><small>Na sua mesa de áudio</small></div><div class="stat"><span class="caption">ARQUIVOS</span><strong style="font-size:25px">${bytes(o.bytes)}</strong><small>de ${bytes(o.limit)}</small><div class="storage-meter"><i style="width:${Math.min(100,o.bytes/o.limit*100)}%"></i></div></div></section><div class="section-title"><h2>Continue de onde parou</h2><a class="fine" href="app.html#playlists">Todas as playlists →</a></div><div class="playlist-grid">${o.playlists.length?o.playlists.slice(0,6).map(card).join(''):emptyPlaylists()}</div><aside class="onboarding"><div><strong>Um bom começo já tem trilha.</strong><p>Ouça os exemplos e adicione seu favorito direto a uma playlist.</p></div><a class="btn ghost" href="app.html#library">Explorar biblioteca ↗</a></aside>`}
function downloads(){return header('Playlists baixadas','Prontas para tocar sem internet.')+`<div class="playlist-grid">${state.savedBoards.length?state.savedBoards.map((b,i)=>card({...b.playlist,tracks_count:b.tracks.length},i)).join(''):'<div class="empty-state"><h2>Nenhuma playlist baixada.</h2><p>Abra uma playlist e escolha Baixar para uso offline.</p><a class="btn primary" href="app.html#playlists">Suas playlists</a></div>'}</div>`}
function playlists(){return header('Suas playlists','Um lugar para cada evento, projeto ou ideia.',newButton)+`<p class="fine" role="status" id="playlist-order-status">${movingPlaylists?'Salvando ordem…':state.offline?'':'Segure a alça ⠿ e arraste para organizar suas playlists.'}</p><div class="playlist-grid">${state.overview.playlists.length?state.overview.playlists.map(card).join(''):emptyPlaylists()}</div>`}
function sampleCard(s,i){return `<article class="sample-card"><div class="sample-cover" aria-hidden="true">${Array.from({length:28},(_,n)=>`<i style="height:${12+((n*17+i*13)%53)}px"></i>`).join('')}</div><h3>${esc(s.name)}</h3><p>${esc(libraryCategories(s).join(' · '))} · ${s.duration} · ${esc(s.author)}</p><div class="actions"><button class="btn ghost" data-action="preview" data-id="${s.id}">${preview?.id===s.id?'■ Parar':'▶ Ouvir'}</button><button class="btn primary" data-action="add-sample" data-id="${s.id}">＋ Adicionar à playlist</button><button class="btn ghost" data-action="download-sample" data-id="${s.id}">↓ Baixar</button></div><p class="credit">${esc(s.credit)} ${s.licenseUrl?`<a href="${esc(s.licenseUrl)}" target="_blank" rel="noopener">${esc(s.license)}</a>`:esc(s.license)}${s.source?` · <a href="${esc(s.source)}" target="_blank" rel="noopener">Fonte</a>`:''}</p></article>`}
function library(){const samples=state.samples.filter(s=>(state.category==='Todos'||libraryCategories(s).includes(state.category))&&(s.name+' '+libraryCategories(s).join(' ')+' '+s.author).toLowerCase().includes(state.search.toLowerCase()));return header('Encontre seu próximo som.','Ouça, baixe ou adicione direto a uma playlist.',state.me.access.is_admin?'<a class="btn ghost" href="app.html#admin-library">Gerenciar biblioteca</a>':'')+`<p class="fine" id="audio-ready" role="status"></p><div class="toolbar"><input id="sample-search" type="search" aria-label="Buscar áudio" placeholder="Buscar por nome, estilo ou autor" value="${esc(state.search)}"></div><div class="filters" aria-label="Categorias">${['Todos',...new Set(state.samples.flatMap(libraryCategories))].map(c=>`<button class="filter ${state.category===c?'active':''}" data-action="filter" data-category="${esc(c)}" aria-pressed="${state.category===c}">${esc(c)}</button>`).join('')}</div><div class="sample-grid">${samples.map(sampleCard).join('')||'<div class="empty-state"><h2>Nenhum som encontrado.</h2><p>Tente outro termo ou escolha outra categoria.</p></div>'}</div>`}
function board(){const {playlist:p,tracks}=state.board;return header(p.name,p.description||'Toque uma faixa para começar.',`<a class="btn ghost" href="app.html#playlists">← Playlists</a><button class="btn ghost" data-action="share-playlist">↗ Compartilhar</button><button class="btn ghost" data-action="playlist-settings">⚙ Configurações</button><button class="btn ghost" data-action="pick-library">＋ Biblioteca</button><button class="btn ghost" data-action="event-mode">⛶ Modo evento</button><button class="btn ghost" data-action="save-device">↓ Baixar para uso offline</button><button class="btn ghost" data-action="clear-device">Remover download</button><button class="btn primary" data-action="upload" ${playlistBatchBusy?'disabled':''}>＋ Importar áudios</button><button type="button" class="btn ghost" data-action="show-playlist-uploads" ${currentPlaylistBatch()?.dismissed?'':'hidden'}>Envios pendentes</button>`)+`<div class="board-head"><span class="pill" id="audio-ready" role="status">Preparando áudios…</span><span class="pill">${tracks.length} faixas</span>${state.savedBoards.some(b=>b.playlist.id===p.id)?(state.savedBoards.find(b=>b.playlist.id===p.id).tracks.map(t=>t.id).join()===tracks.map(t=>t.id).join()?'<span class="pill">✓ Disponível offline</span>':'<span class="pill">Atualize o download</span>'):''}<span class="pill">${p.play_mode==='single'?'Uma por vez':'Faixas simultâneas'}</span>${p.loop?'<span class="pill">↻ Loop ativado</span>':''}<a class="fine" href="app.html#library">Adicionar exemplos da biblioteca →</a></div><div id="playlist-upload-panel">${playlistUploadMarkup()}</div><p id="order-status" class="fine" role="status">${moving?'Salvando ordem…':'Segure a alça ⠿ e arraste para organizar as faixas.'}</p><div class="pads" aria-busy="${moving}">${tracks.length?tracks.map((t,i)=>`<div data-track-id="${t.id}" class="pad ${active.has(t.id)?'playing':''}" style="${playlistColorStyle(t.color,'pad')}"><button class="pad-trigger" data-action="play" data-id="${t.id}" aria-pressed="${active.has(t.id)}"><span class="pad-top"><span class="play-icon">${active.has(t.id)?(p.retrigger==='restart'?'↻':'⏸'):'▶'}</span><span class="key">${i<9?i+1:'♫'}</span></span><span><strong>${esc(t.name)}</strong><small>${active.has(t.id)?'Tocando agora':t.sample_id?'Da biblioteca Sysmacom Harmony':esc(t.filename||'Seu áudio')}</small></span></button><div class="pad-actions"><button type="button" class="pad-drag" aria-label="Reordenar ${esc(t.name)}: segure e arraste ou use as setas do teclado" aria-pressed="false" title="Segure e arraste para mudar a ordem">⠿</button><button type="button" class="pad-delete" data-action="delete-track" data-id="${t.id}" aria-label="Excluir ${esc(t.name)}">Excluir</button><button class="pad-edit" data-action="track-settings" data-id="${t.id}" aria-label="Editar ${esc(t.name)}">✎</button></div></div>`).join(''):`<div class="empty-state"><div class="empty-icon">♫</div><h2>Vamos dar som a esta playlist?</h2><p>Importe um arquivo de áudio ou escolha um exemplo da biblioteca.</p><button class="btn primary" data-action="upload" ${playlistBatchBusy?'disabled':''}>＋ Importar áudios</button> <a class="btn ghost" href="app.html#library">Explorar biblioteca</a></div>`}</div><p class="fine" style="margin-top:22px">Atalhos 1–9 para tocar · Esc para parar tudo · Arquivos de até ${Math.round(accountLimits(state.me?.limits).file/MiB)} MB</p><p id="upload-status" class="fine" role="status" aria-live="polite"></p><input id="upload-input" type="file" multiple accept="audio/*,.mp3,.wav,.ogg,.m4a,.flac,.aac,.wma" hidden>`}
function profile(){const p=state.me.profile,w=state.me.workspace;return header('Seu perfil','Do seu jeito, em todos os seus projetos.')+`<form class="form-panel" id="profile-form"><div class="profile-heading"><div class="avatar" style="background:${esc(p.accent)}22;color:${esc(p.accent)}">${esc(p.display_name.slice(0,1).toUpperCase())}</div><div><h2>${esc(p.display_name)}</h2><p>${esc(p.email)}</p></div></div><div class="settings-grid"><div class="field"><label for="profile-name">Como podemos chamar você?</label><input id="profile-name" name="display_name" required maxlength="80" value="${esc(p.display_name)}" autocomplete="name"></div><div class="field"><label for="workspace-title">Nome do seu estúdio</label><input id="workspace-title" name="workspace_name" required maxlength="80" value="${esc(w.name)}"></div></div><div class="field"><label for="profile-bio">Sobre você</label><textarea id="profile-bio" name="bio" maxlength="300" placeholder="Criador, apresentador, DJ…">${esc(p.bio)}</textarea></div><div class="field"><label for="profile-color">Sua cor</label><input id="profile-color" type="color" name="accent" value="${esc(p.accent)}" style="width:90px"></div><button class="btn primary" type="submit">Salvar perfil</button><div class="divider"></div><p class="fine">O e-mail é fornecido pelo login da sua conta. Seu espaço e seus arquivos são privados.</p><button class="btn ghost" data-action="signout" type="button">Sair da conta ↗</button></form><section class="form-panel" style="margin-top:22px"><h2 style="font-size:20px">Seus backups</h2><p class="fine">Importe playlists de um backup ou exporte uma cópia dos seus áudios. Os itens que já estão na sua conta serão mantidos.</p><button class="btn ghost" data-action="import-backup">↑ Importar backup</button><input type="file" accept="application/json" id="backup-input" hidden><div class="divider"></div><button class="btn ghost" data-action="export-backup">↓ Exportar minhas playlists e áudios</button></section>`}
let routeVersion=0;
async function navigate(){const version=++routeVersion;let [route='dashboard',id]=(location.hash.slice(1)||'dashboard').split('/');if(state.offline&&!['dashboard','playlists','downloads','studio'].includes(route))route='downloads';if(document.body.classList.contains('event-mode'))await eventMode(false);const old=state.board;const leaving=old&&(route!=='studio'||id!==old.playlist.id);if(leaving&&old.playlist.switch_mode==='stop'){for(const [tid,item]of [...active])if(item.playlistId===old.playlist.id)stopOne(tid)}state.route=route;if(preview)stopPreview();$('#view').innerHTML='<div class="loading" role="status">Carregando seu espaço…</div>';for(const a of document.querySelectorAll('[data-nav]'))a.classList.toggle('active',a.dataset.nav===(route==='studio'?'playlists':route));try{if(!await refreshAccess())return;state.savedBoards=await offlinePlaylists.boards(state.me.profile.id).catch(()=>[]);if(route==='community')state.community=await api('/community');if(route==='library')state.samples=await api('/samples');if(route==='contributions')state.contributions=await api('/contributions');if(route==='admin-library'){if(!state.me.access.is_admin)throw Error('Acesso exclusivo do administrador.');state.libraryAdmin=await api('/admin/library');state.pendingContributions=await api('/admin/contributions');state.samples=await api('/samples')}if(route==='admin'){if(!state.me.access.is_admin)throw Error('Acesso exclusivo do administrador.');state.accounts=await api('/admin/accounts')}state.overview=await api('/overview');if(version!==routeVersion)return;if(route==='shared'){const shared=await api('/shared/'+encodeURIComponent(id));if(version!==routeVersion)return;state.shared={...shared,token:id}}if(route==='studio'){const b=await api('/playlists/'+encodeURIComponent(id));if(version!==routeVersion)return;state.board=b}else state.board=null;render();if(state.route==='admin')void refreshAdminNotifications();window.scrollTo(0,0)}catch(e){if(version!==routeVersion)return;if(!state.offline&&(navigator.onLine===false||isConnectionError(e))&&await enterOffline())return navigate();$('#view').innerHTML=`<div class="error-panel"><h2>Não foi possível abrir seu estúdio.</h2><p>${esc(e.message)}</p><button class="btn" data-action="retry">Tentar novamente</button> <a class="btn ghost" href="app.html#dashboard">Voltar ao painel</a> <a class="btn ghost" href="login.html">Entrar novamente</a></div>`}}
function render(){if(state.me?.access?.status!=='approved'){renderAccessGate();return}const views={dashboard:state.offline?downloads:dashboard,downloads,playlists,library,studio:board,profile,admin:adminPanel,'admin-library':adminLibraryPanel,contributions:contributionsPanel,shared:sharedPlaylistPanel,community:communityPanel};$('#view').innerHTML=(views[state.route]||dashboard)();$('#breadcrumb').textContent={dashboard:'Visão geral',playlists:'Suas playlists',downloads:'Playlists baixadas',library:'Biblioteca de exemplos',studio:'Mesa de áudio',profile:'Meu perfil',admin:'Administração','admin-library':'Gerenciar biblioteca',contributions:'Minhas contribuições',shared:'Playlist da comunidade',community:'Playlists da comunidade'}[state.route]||'Meu estúdio';offlineUI();updateTransport();updatePreviewButtons();primeAudio();updateReadiness()}
function updateAccount(){$('#admin-nav').hidden=!state.me?.access?.is_admin;$('#admin-library-nav').hidden=!state.me?.access?.is_admin;offlineUI();$('#account-name').textContent=state.me.profile.display_name;$('#account-initial').textContent=state.me.profile.display_name.slice(0,1).toUpperCase();$('#workspace-name').textContent=state.me.workspace.name}
function updateTransport(){
 const group=playbackState(active),items=group.audible;
 const previewPlaying=preview?.playing&&!preview.audio.paused&&!preview.audio.ended;
 const approved=state.me?.access?.status==='approved',event=document.body.classList.contains('event-mode');
 const visible=approved&&(event||items.length>0||previewPlaying);
 $('.transport').hidden=!visible;document.body.classList.toggle('transport-open',visible);
 const shown=items.length?items:group.selected;
 $('#now-playing').textContent=shown.length?shown.map(x=>x.name).join(' + '):previewPlaying?preview.name:'Tudo pronto para o próximo play';
 $('#now-playing').title=$('#now-playing').textContent;
 const count=(n,singular,plural)=>`${n} ${n===1?singular:plural}`;
 $('#play-count').textContent=items.length?count(items.length,'faixa tocando','faixas tocando')+(group.paused.length?' · '+count(group.paused.length,'pausada','pausadas'):''):group.paused.length?count(group.paused.length,'faixa pausada','faixas pausadas'):group.selected.length?'Preparando áudio…':previewPlaying?'Prévia tocando':'Nenhuma faixa tocando';
 const fade=eventFader.state();if(fade?.started&&!fade.paused)$('#play-count').textContent=fade.kind==='pause'?'Pausando faixa…':fade.kind==='resume'?'Retomando faixa…':'Transição entre faixas';
 const resume=group.action==='resume';$('#pause-all').textContent=resume?'▶ Continuar':'⏸ Pausar';
 $('#pause-all').setAttribute('aria-label',resume?'Continuar faixas pausadas':'Pausar todas as faixas');
 $('#pause-all').disabled=!group.selected.length;$('#stop-all').disabled=!group.selected.length&&!preview;
 for(const b of document.querySelectorAll('[data-action="play"]')){
  const selected=active.get(b.dataset.id),pausing=fade?.kind==='pause'&&fade.incoming===b.dataset.id,paused=selected?.pausedByUser||(selected?.ready===true&&selected.audio.paused&&!selected.resuming);
  b.setAttribute('aria-pressed',String(!!selected));b.closest('.pad').classList.toggle('playing',!!selected&&!paused);
  const restart=state.board?.playlist.retrigger==='restart';b.querySelector('.play-icon').textContent=paused||pausing?'▶':selected?(restart?'↻':'⏸'):'▶';
  b.setAttribute('aria-label',`${paused||pausing?'Continuar':selected?(restart?'Recomeçar':'Pausar'):'Tocar'} ${state.board?.tracks.find(t=>t.id===b.dataset.id)?.name||''}`);
  const subtitle=b.querySelector('small'),track=state.board?.tracks.find(t=>t.id===b.dataset.id);
  if(subtitle)subtitle.textContent=pausing?'Pausando…':paused?'Pausada':selected?'Tocando agora':track?.sample_id?'Da biblioteca Sysmacom Harmony':track?.filename||'Seu áudio';
 }
}
function stopOne(id){eventFader.removing(id);removePlayingTrack(id)}
function removePlayingTrack(id){const item=active.get(id);if(!item)return;active.delete(id);audioLevels.release(item);if(item.localURL){URL.revokeObjectURL(item.localURL);const entry=preparedAudio.get(id);if(entry?.audio===item.audio){item.audio.removeAttribute('src');entry.state='idle';item.audio.load()}}item.audio.onended=null;item.audio.onerror=null;item.audio.onplaying=null;item.audio.onpause=null;item.audio.onwaiting=null;item.audio.pause();if(preparedAudio.get(id)?.audio===item.audio){preparedAudio.stop(id)}else{item.audio.removeAttribute('src');item.audio.load()}updateTransport()}
function stopAll(){eventFader.reset();for(const id of [...active.keys()])stopOne(id);if(preview)stopPreview();updateTransport()}
async function play(id){
 const p=state.board?.playlist,t=state.board?.tracks.find(x=>x.id===id);if(!p||!t)return;if(preview)stopPreview();
 const fading=usesEventFader(),unlock=fading?audioLevels.unlock():audioLevels.wake();
 // Begin unlocking on the gesture, but report errors through the loader below.
 let unlockError;const unlocked=unlock.catch(error=>{unlockError=error});
 for(const [key,item]of [...active])if(key!==id&&item.pausedByCard&&item.audio.paused)stopOne(key);
 const selected=active.get(id),fade=eventFader.state(),pausing=fade?.kind==='pause'&&fade.incoming===id;
 if(selected?.pausedByUser||(selected?.ready===true&&selected.audio.paused&&!selected.resuming)||pausing){
  await unlocked;if(active.get(id)!==selected)return;if(unlockError){toast('Não foi possível continuar o áudio. Toque novamente.',true);return}
  const card=selected.pausedByCard||pausing;
  if(card){selected.pausedByCard=false;if(fading)eventFader.resumeCard(id);else audioLevels.set(selected,1)}else if(fading)eventFader.resume();
  const errors=await resumeTracks(active,fading&&!card?[...active.keys()]:[id]);
  if(errors.length&&active.get(id)===selected&&card){selected.pausedByCard=true;if(fading)eventFader.pauseCard(id,true)}
  updateTransport();if(errors.length)toast('Não foi possível continuar. Toque novamente para tentar.',true);return;
 }
 if(selected){if(p.retrigger!=='restart'){selected.pausedByCard=true;if(fading)eventFader.pauseCard(id);else pauseTracks(active,[id]);updateTransport();return}stopOne(id)}
 if(!fading&&p.play_mode==='single')stopAll();
 const fadeLevel=fading?eventFader.prepare(id):1,cached=preparedAudio.get(id),prepared=cached?.state==='error'?null:cached;
 const audio=prepared?.audio||new Audio();if(!prepared)audio.crossOrigin='anonymous';audio.loop=!!p.loop;
 const item={audio,name:t.name,playlistId:p.id,ready:false,fadeLevel};active.set(id,item);
 audio.onplaying=()=>{if(active.get(id)===item){if(item.pausedByUser){audio.pause();return}item.playing=true;eventFader.started(id);updateTransport()}};
 audio.onpause=()=>{if(active.get(id)===item){item.playing=false;updateTransport()}};
 audio.onwaiting=()=>{if(active.get(id)===item){item.playing=false;eventFader.buffering(id);updateTransport()}};
 audio.onended=()=>{if(active.get(id)===item)stopOne(id)};
 audio.onerror=()=>{if(active.get(id)===item){stopOne(id);toast('Não foi possível tocar. Confira a conexão e tente novamente.',true)}};updateTransport();
 try{
  await unlocked;if(active.get(id)!==item)return;if(unlockError)throw Error('Não foi possível preparar o áudio. Toque novamente.');audioLevels.set(item,item.fadeLevel);
  if(!audio.src.startsWith('blob:')){const owner=state.me.profile.id,board=structuredClone(state.board),me=structuredClone(state.me),sessionVersion=deviceSessionVersion;const {blob,saved}=await deviceAudio.get({owner,id:cacheId(t),trackId:t.id,size:t.file_size||0,network:!state.offline,url:async()=> (await getBackend()).audioURL(id)});if(active.get(id)!==item)return;item.localURL=URL.createObjectURL(blob);audio.src=item.localURL;if(saved)void rememberHeardPlaylist(board,me,sessionVersion)}
  if(active.get(id)!==item)return;item.ready=true;audio.currentTime=0;if(!item.pausedByUser){const version=item.playbackVersion=(item.playbackVersion||0)+1;try{await audio.play()}catch(error){if(item.playbackVersion!==version)return;throw error}}else updateTransport();
 }catch(e){if(active.get(id)===item){if(item.pausedByUser&&e.name==='AbortError'){updateTransport();return}stopOne(id);toast(e.message||'Não foi possível iniciar o áudio.',true)}}
}

function modal(title,html,handler,submit='Salvar'){lastFocus=document.activeElement;$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal-submit').textContent=submit;$('#modal-submit').className='btn primary';modalHandler=handler;$('#modal').showModal();setTimeout(()=>$('#modal-body').querySelector('input,select,button')?.focus(),0)}
function closeModal(){if(accountDeletionBusy)return;$('#modal').close();modalHandler=null;if(lastFocus?.isConnected)lastFocus.focus()}
$('#modal-cancel').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const b=$('#modal').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal()}});$('#modal').addEventListener('cancel',event=>{if(accountDeletionBusy){event.preventDefault();return}modalHandler=null});$('#modal-form').onsubmit=async e=>{e.preventDefault();if(!modalHandler)return;$('#modal-submit').disabled=true;try{await modalHandler(new FormData(e.target));closeModal()}catch(error){toast(error.message,true)}finally{$('#modal-submit').disabled=false}};
function newPlaylist(){modal('Nova playlist',`<div class="field"><label for="new-name">Nome da playlist</label><input id="new-name" name="name" required maxlength="80" placeholder="Ex.: Meu podcast"></div><div class="field"><label for="new-description">Descrição</label><textarea id="new-description" name="description" maxlength="300" placeholder="Prepare o próximo momento."></textarea></div><div class="field"><label for="new-color">Cor</label><input id="new-color" name="color" type="color" value="#78b5ff"></div>`,async form=>{const p=await api('/playlists',{method:'POST',body:Object.fromEntries(form)});location.hash='studio/'+p.id;toast('Playlist criada. Agora vamos dar o play.');},'Criar playlist')}
function playlistSettings(){const p=state.board.playlist;modal('Configurações da playlist',`<div class="field"><label for="setting-name">Nome</label><input id="setting-name" name="name" value="${esc(p.name)}" maxlength="80" required></div><div class="field"><label for="setting-description">Descrição</label><textarea id="setting-description" name="description" maxlength="300">${esc(p.description)}</textarea></div><div class="field"><label for="setting-mode">Reprodução das faixas</label><select id="setting-mode" name="play_mode"><option value="mix" ${p.play_mode==='mix'?'selected':''}>Simultânea · misturar faixas</option><option value="single" ${p.play_mode==='single'?'selected':''}>Uma por vez · parar todas as anteriores</option></select></div><div class="field"><label for="setting-fader">Fader no modo evento</label><select id="setting-fader" name="event_fade_enabled"><option value="true" ${p.event_fade_enabled!==false?'selected':''}>Ativado · transição entre duas faixas</option><option value="false" ${p.event_fade_enabled===false?'selected':''}>Desativado</option></select></div><div class="field"><label for="setting-fade-duration">Duração da transição</label><select id="setting-fade-duration" name="event_fade_duration">${[1,2,3,5].map(seconds=>`<option value="${seconds*1000}" ${(p.event_fade_duration??2000)===seconds*1000?'selected':''}>${seconds} ${seconds===1?'segundo':'segundos'}</option>`).join('')}</select></div><div class="field"><label for="setting-loop">Ao terminar uma faixa</label><select id="setting-loop" name="loop"><option value="false">Encerrar reprodução</option><option value="true" ${p.loop?'selected':''}>Repetir em loop</option></select></div><div class="field"><label for="setting-retrigger">Ao tocar novamente na mesma faixa</label><select id="setting-retrigger" name="retrigger"><option value="stop">Pausar e continuar do mesmo ponto</option><option value="restart" ${p.retrigger==='restart'?'selected':''}>Recomeçar do início</option></select></div><div class="field"><label for="setting-switch">Ao mudar de playlist</label><select id="setting-switch" name="switch_mode"><option value="stop">Parar os áudios desta playlist</option><option value="continue" ${p.switch_mode==='continue'?'selected':''}>Continuar tocando</option></select></div><div class="field"><label for="setting-color">Cor da playlist</label><input id="setting-color" name="color" type="color" value="${esc(p.color)}"></div><div class="divider"></div><button class="btn danger" type="button" data-action="delete-playlist">Excluir playlist</button>`,async form=>{const b=Object.fromEntries(form);b.loop=b.loop==='true';b.event_fade_enabled=b.event_fade_enabled==='true';b.event_fade_duration=Number(b.event_fade_duration);await api('/playlists/'+p.id,{method:'PATCH',body:b});if(b.play_mode==='single')stopAll();else for(const x of active.values())if(x.playlistId===p.id)x.audio.loop=b.loop;state.board=await api('/playlists/'+p.id);render();toast('Configurações salvas.');})}
const deletingTracks=new Set();
async function deleteTrack(id){
const board=state.board,track=board?.tracks.find(t=>t.id===id);
if(!track||deletingTracks.has(id)||!confirm(`Excluir “${track.name}”? O áudio será removido desta playlist.`))return;
deletingTracks.add(id);stopOne(id);
const buttons=[...document.querySelectorAll('[data-action="delete-track"]')].filter(b=>b.dataset.id===id);buttons.forEach(b=>b.disabled=true);
try{
await api('/tracks/'+id,{method:'DELETE'});
if($('#modal').open&&$('#modal-body [data-action="delete-track"]')?.dataset.id===id)closeModal();
if(state.board?.playlist.id===board.playlist.id){const refreshed=await api('/playlists/'+board.playlist.id);if(state.board?.playlist.id===board.playlist.id){state.board=refreshed;render()}}
toast('Áudio excluído.');
}finally{deletingTracks.delete(id);buttons.forEach(b=>{if(b.isConnected)b.disabled=false})}
}
function trackSettings(id){const t=state.board.tracks.find(x=>x.id===id);modal('Editar faixa',`<div class="field"><label for="track-name">Nome</label><input id="track-name" name="name" required maxlength="80" value="${esc(t.name)}"></div><div class="field"><label for="track-color">Cor do botão</label><input id="track-color" name="color" type="color" value="${esc(t.color)}"></div><button type="button" class="btn ghost" data-action="download-track" data-id="${t.id}">↓ Baixar áudio</button>${t.audio_path?`<button type="button" class="btn ghost" data-action="contribute-track" data-id="${t.id}">↑ Enviar para a biblioteca</button>`:''}<div class="divider"></div><button class="btn danger" type="button" data-action="delete-track" data-id="${t.id}">Excluir faixa</button>`,async form=>{await api('/tracks/'+t.id,{method:'PATCH',body:Object.fromEntries(form)});if(active.has(t.id))active.get(t.id).name=form.get('name');state.board=await api('/playlists/'+state.board.playlist.id);render();toast('Faixa atualizada.')})}
function addSample(id){const sample=state.samples.find(s=>s.id===id),lists=state.overview.playlists;if(!lists.length){toast('Crie uma playlist para adicionar este som.');newPlaylist();return}modal('Adicionar à sua mesa',`<p class="fine">${esc(sample.name)} · ${esc(sample.license)}</p><div class="field"><label for="target-playlist">Escolha a playlist</label><select id="target-playlist" name="playlist_id">${lists.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="sample-name">Nome do botão</label><input id="sample-name" name="name" required maxlength="80" value="${esc(sample.name)}"></div><p class="fine">${esc(sample.credit)}</p>`,async f=>{const target=await api('/playlists/'+f.get('playlist_id'));if(target.tracks.some(t=>t.sample_id===id)&&!confirm('Esta música já está na playlist '+target.playlist.name+'. Deseja adicionar outra cópia?'))throw Error('Nenhuma cópia adicionada.');await api('/playlists/'+f.get('playlist_id')+'/tracks',{method:'POST',body:{sample_id:id,name:f.get('name')}});toast('Som adicionado à playlist.');render()},'Adicionar faixa')}
async function previewSample(id){const sample=state.samples.find(s=>s.id===id);if(!sample)return;if(preview?.id===id){if(!sampleAudio.paused||!samplePreview.current){stopPreview();return}await samplePreview.toggle(samplePreview.current);return}stopPreview();const version=previewLoadVersion,owner=state.me.profile.id;$('#sample-preview').hidden=false;$('#preview-title').textContent=sample.name;$('#preview-status').textContent='Carregando o exemplo…';preview={id,audio:sampleAudio,name:sample.name,playing:false};updatePreviewButtons();
// Unlock the attached media element on this gesture before reading/downloading.
sampleAudio.muted=true;sampleAudio.src='data:audio/wav;base64,UklGRiwAAABXQVZFZm10IBAAAAABAAEAQB8AAIA+AAACABAAZGF0YQgAAAAAAAAAAAAAAA==';sampleAudio.play().catch(()=>{});
try{const {blob}=await deviceAudio.get({owner,id:'@library:'+sample.id,url:sample.url,size:sample.file_size||0,network:!state.offline});if(version!==previewLoadVersion)return;sampleAudio.pause();previewURL=URL.createObjectURL(blob);sampleAudio.volume=Number($('#master-volume').value)/100;await samplePreview.toggle({id,url:previewURL,title:sample.name})}catch(error){if(version!==previewLoadVersion)return;stopPreview();toast(error.message||'Não foi possível ouvir. Tente novamente.',true)}}
function currentPlaylistBatch(){return state.board?playlistBatches.get(state.me.profile.id+'/'+state.board.playlist.id):null}
function playlistUploadMarkup(){
 const job=currentPlaylistBatch();if(!job||job.dismissed)return '';const counts=batchCounts(job);
 return `<section class="playlist-upload-summary form-panel" aria-label="Importação de áudios"><h2>Importação de áudios</h2><p role="status" aria-live="polite">${counts.done} de ${counts.total} adicionados${counts.failed?' · '+counts.failed+' com falha':''}${job.busy?' · Importando…':counts.pending?' · '+counts.pending+' pendentes':''}</p><ul>${job.entries.map(entry=>`<li><strong>${esc(entry.filename)}</strong><span>${entry.status==='failed'?'Falha: '+esc(entry.error):entry.status==='done'?'Adicionado':esc(entry.stage||'Aguardando')}</span></li>`).join('')}</ul>${!job.busy&&!playlistBatchBusy&&(counts.failed||counts.pending)?'<button type="button" class="btn primary" data-action="retry-playlist-upload">Tentar novamente os pendentes</button>':''}${!job.busy&&!playlistBatchBusy?'<button type="button" class="btn ghost" data-action="dismiss-playlist-upload">Fechar</button>':''}</section>`;
}
function updatePlaylistUpload(){const panel=$('#playlist-upload-panel');if(panel)panel.innerHTML=playlistUploadMarkup();for(const button of document.querySelectorAll('[data-action="upload"]'))button.disabled=playlistBatchBusy;const reopen=$('[data-action="show-playlist-uploads"]');if(reopen){const job=currentPlaylistBatch();reopen.hidden=!job?.dismissed;reopen.disabled=playlistBatchBusy}}
async function upload(files){
 if(playlistBatchBusy)throw Error('Aguarde a importação em andamento.');if(!files?.length||!state.board)return;
 const p=state.board.playlist,key=state.me.profile.id+'/'+p.id,previous=playlistBatches.get(key);
 if(previous&&batchCounts(previous).done<previous.entries.length&&!confirm('Substituir os arquivos pendentes por uma nova seleção?'))return;
 const job=createPlaylistBatch(files,{owner:state.me.profile.id,playlistId:p.id,playlistName:p.name});playlistBatches.set(key,job);await importPlaylistBatch(job);
}
async function importPlaylistBatch(job){
 if(playlistBatchBusy||job.owner!==state.me.profile.id)return;playlistBatchBusy=true;job.cancelled=false;updatePlaylistUpload();let counts;
 try{
  counts=await runPlaylistBatch(job,{maxBytes:state.me.limits.file,isCurrent:()=>!job.cancelled&&state.me?.profile.id===job.owner&&state.me.access.status==='approved',onChange:updatePlaylistUpload,upload:async(entry,prepared)=>api('/playlists/'+encodeURIComponent(job.playlistId)+'/upload',{method:'POST',body:prepared.blob,headers:{'Content-Type':prepared.blob.type||'application/octet-stream','X-File-Name':encodeURIComponent(prepared.filename),'X-Upload-Id':entry.id}})});
  if(!job.cancelled&&state.me?.profile.id===job.owner&&state.route==='studio'&&state.board?.playlist.id===job.playlistId){try{state.board=await api('/playlists/'+encodeURIComponent(job.playlistId));render()}catch{toast('Os envios terminaram. Atualize a playlist para ver os áudios.',true)}}
  if(!job.cancelled&&state.me?.profile.id===job.owner)toast(`${counts.done} de ${counts.total} áudios adicionados${counts.failed?' · '+counts.failed+' com falha':''}${counts.pending?' · '+counts.pending+' pendentes':''}.`,!!counts.failed);
 }finally{playlistBatchBusy=false;updatePlaylistUpload()}
}

async function importBackup(file){if(!file)return;if(file.size>300*1024*1024)throw Error('Backup excede 300 MB.');const data=validateBackup(JSON.parse(await file.text()),{maxFileBytes:accountLimits(state.me?.limits).file});if(!confirm(`Importar ${data.playlists.length} playlists para sua conta?`))return;let imported=0;for(const p of data.playlists){const created=await api('/playlists',{method:'POST',body:{name:p.name,color:p.pads?.[0]?.color||'#78b5ff'}});const opts=p.settings||{};await api('/playlists/'+created.id,{method:'PATCH',body:{name:p.name,description:'Importada do Sysmacom Harmony',color:p.pads?.[0]?.color||'#78b5ff',play_mode:opts.playmode==='single'?'single':'mix',loop:opts.repeat==='on',retrigger:opts.retrigger==='restart'?'restart':'stop',switch_mode:opts.switchmode==='continue'?'continue':'stop',event_fade_enabled:opts.event_fade_enabled!==false,event_fade_duration:opts.event_fade_duration??2000}});for(const t of p.pads||[]){const encoded=data.audio[t.file];if(!encoded)continue;const blob=await(await fetch(encoded)).blob();await api('/playlists/'+created.id+'/upload?name='+encodeURIComponent(t.name),{method:'POST',body:blob,headers:{'Content-Type':blob.type,'X-File-Name':encodeURIComponent(t.filename||t.name)}});imported++;toast(`${imported} faixas importadas…`)}}await navigate();toast('Backup importado. Seus projetos anteriores foram mantidos.')}
async function exportBackup(){toast('Preparando backup. Mantenha esta página aberta.');const o=await api('/overview'),data={version:1,current:null,volume:$('#master-volume').value,playlists:[],audio:{}};for(const p of o.playlists){const b=await api('/playlists/'+p.id);const output={id:p.id,name:p.name,settings:{playmode:p.play_mode,repeat:p.loop?'on':'off',retrigger:p.retrigger,switchmode:p.switch_mode,event_fade_enabled:p.event_fade_enabled!==false,event_fade_duration:p.event_fade_duration??2000},pads:[]};for(const t of b.tracks){const {blob}=await(await getBackend()).blobForTrack(t.id);data.audio[t.id]=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(blob)});output.pads.push({id:t.id,name:t.name,color:t.color,file:t.id,filename:t.filename||t.name})}data.playlists.push(output)}data.current=data.playlists[0]?.id;const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='sysmacom-harmony-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Backup exportado.')}
$('#view').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;if(state.offline&&!['play','event-mode','clear-device','retry','reconnect','signout'].includes(action)){toast('Conecte-se à internet para usar esta opção.');return}try{if(action==='share-playlist')await sharePlaylist();if(action==='import-shared'){b.disabled=true;try{const imported=await api('/shared/'+state.shared.token+'/import',{method:'POST',onUploadStage:message=>{if(b.isConnected)b.textContent=message}});location.hash='studio/'+imported.playlist_id;toast('Playlist adicionada às suas playlists.')}finally{if(b.isConnected){b.disabled=false;b.textContent='Adicionar às minhas playlists'}}}if(action==='pick-library')pickLibrary();if(action==='insert-library')await insertLibrary(id,b);if(action==='event-mode')await eventMode();if(action==='save-device')await saveDevice(b);if(action==='clear-device'){if(!confirm('Remover o download desta playlist?'))return;await offlinePlaylists.remove(state.me.profile.id,state.board.playlist.id);state.savedBoards=await offlinePlaylists.boards(state.me.profile.id);if(state.offline)location.hash='downloads';else render();toast('Download removido.')}if(action==='reconnect')await reconnect();if(action==='signout')await signout();if(action==='download-sample'){b.disabled=true;try{const sample=state.samples.find(s=>s.id===id);const {blob}=await deviceAudio.get({owner:state.me.profile.id,id:'@library:'+id,url:sample.url,size:sample.file_size||0});saveBlob(blob,sample.filename)}finally{b.disabled=false}}if(action==='new-playlist')newPlaylist();if(action==='playlist-settings')playlistSettings();if(action==='delete-track')await deleteTrack(id);if(action==='track-settings')trackSettings(id);if(action==='play')await play(id);if(action==='upload'&&!playlistBatchBusy)$('#upload-input').click();if(action==='retry-playlist-upload'){const job=currentPlaylistBatch();if(job)await importPlaylistBatch(job);}if(action==='dismiss-playlist-upload'&&!playlistBatchBusy){const job=currentPlaylistBatch();if(job){if(batchCounts(job).done===job.entries.length)playlistBatches.delete(job.owner+'/'+job.playlistId);else job.dismissed=true;updatePlaylistUpload()}}if(action==='show-playlist-uploads'){const job=currentPlaylistBatch();if(job){job.dismissed=false;updatePlaylistUpload()}}if(action==='preview')await previewSample(id);if(action==='add-sample')addSample(id);if(action==='filter'){state.category=b.dataset.category;render()}if(action==='retry')await navigate();if(action==='reload')location.reload();if(action==='import-backup')$('#backup-input').click();if(action==='export-backup'){b.disabled=true;await exportBackup();b.disabled=false}}catch(error){b.disabled=false;toast(error.message,true)}});
$('#modal-body').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{if(b.dataset.action==='download-track'){b.disabled=true;try{const track=state.board.tracks.find(t=>t.id===b.dataset.id);const {blob}=await deviceAudio.get({owner:state.me.profile.id,id:cacheId(track),trackId:track.id,size:track.file_size||0,url:async()=> (await getBackend()).audioURL(track.id)});saveBlob(blob,track.filename||track.name)}finally{b.disabled=false}}if(b.dataset.action==='delete-playlist'&&confirm('Excluir esta playlist e todos os seus áudios?')){b.disabled=true;const id=state.board.playlist.id;await api('/playlists/'+id,{method:'DELETE'});for(const [tid,x]of [...active])if(x.playlistId===id)stopOne(tid);state.board=null;closeModal();location.hash='playlists';toast('Playlist excluída.')}if(b.dataset.action==='delete-track')await deleteTrack(b.dataset.id);}catch(error){b.disabled=false;toast(error.message,true)}});
