$('#pause-all').onclick=async()=>{
 if(!active.size)return;
 if(playbackState(active).action==='resume'){
  try{if(usesEventFader())await audioLevels.unlock();else await audioLevels.wake()}catch{toast('Não foi possível continuar o áudio. Toque novamente.',true);return}
  const card=[...active].find(([,item])=>item.pausedByCard);
  if(usesEventFader()){if(card)eventFader.resumeCard(card[0]);else eventFader.resume()}else if(card)audioLevels.set(card[1],1);
  if(card)card[1].pausedByCard=false;
  const pending=resumeTracks(active);updateTransport();const errors=await pending;
  if(errors.length&&card&&active.get(card[0])===card[1]){card[1].pausedByCard=true;if(usesEventFader())eventFader.pauseCard(card[0],true)}
  updateTransport();if(errors.length)toast('Não foi possível continuar. Toque em Continuar para tentar novamente.',true);
 }else{eventFader.pause();pauseTracks(active);updateTransport()}
};
