function adminPanel(){const statuses={pending:'Pendente',approved:'Liberada',blocked:'Bloqueada'};const counts={pending:0,approved:0,blocked:0};for(const a of state.accounts)counts[a.status]++;
return header('Liberação de contas','Gerencie as solicitações de acesso e as contas do Harmony.','<button class="btn ghost" data-action="refresh-admin">↻ Atualizar</button>')+adminNotificationPanel()+`<section class="stats"><div class="stat"><span class="caption">AGUARDANDO</span><strong>${counts.pending}</strong></div><div class="stat"><span class="caption">LIBERADAS</span><strong>${counts.approved}</strong></div><div class="stat"><span class="caption">BLOQUEADAS</span><strong>${counts.blocked}</strong></div></section><div class="account-list">${state.accounts.map(a=>`<article class="account-review"><div><strong>${esc(a.display_name||a.email)}</strong><p>${esc(a.email)}</p><small>${new Date(a.requested_at).toLocaleDateString('pt-BR')} · <span class="account-status status-${a.status}">${a.deletion_status&&a.deletion_status!=='completed'?'Exclusão pendente':statuses[a.status]}</span></small><p class="fine account-usage">Áudio: ${bytes(accountLimits(a.limits).file)} · Espaço: ${bytes(a.storage_bytes||0)} de ${bytes(accountLimits(a.limits).storage)}</p></div><div class="actions">${!a.deletion_status?`<button type="button" class="btn ghost" data-account-limits="${a.user_id}">Limites</button>`:''}${a.is_admin||a.user_id===state.me.profile.id?'<span class="pill">Administrador</span>':a.deletion_status&&a.deletion_status!=='completed'?`<button type="button" class="btn danger" data-delete-account="${a.user_id}">Concluir exclusão</button>`:`${a.status!=='approved'?`<button class="btn primary" data-review-id="${a.user_id}" data-review-status="approved">Liberar conta</button>`:''}${a.status!=='blocked'?`<button class="btn danger" data-review-id="${a.user_id}" data-review-status="blocked">Bloquear</button>`:`<button class="btn ghost" data-review-id="${a.user_id}" data-review-status="pending">Voltar a pendente</button>`}${a.can_delete?`<button type="button" class="btn danger" data-delete-account="${a.user_id}">Excluir conta</button>`:''}`}</div></article>`).join('')||'<div class="empty-state"><h2>Nenhum cadastro recebido.</h2></div>'}</div><p class="fine" style="margin-top:18px">Mostrando até 200 cadastros mais recentes. A liberação não dá acesso aos áudios de outras contas.</p>`}
function editAccountLimits(id){if(!state.me.access.is_admin||state.offline)return;const account=state.accounts.find(a=>a.user_id===id);if(!account||account.deletion_status)return;const limits=accountLimits(account.limits),gb=limits.storage%GiB===0;
 modal('Limites da conta',`<p>${esc(account.display_name||account.email)}</p><p class="fine">Usado: ${bytes(account.storage_bytes||0)}. Reduzir o espaço não exclui os áudios existentes.</p><div class="field"><label for="account-file-limit">Tamanho máximo por áudio (MB)</label><input type="number" id="account-file-limit" name="file_mb" min="1" max="50" step="1" value="${limits.file/MiB}" required><small>De 1 a 50 MB.</small></div><div class="settings-grid"><div class="field"><label for="account-storage-limit">Espaço das playlists</label><input type="number" id="account-storage-limit" name="storage" min="1" max="${gb?100:102400}" step="1" value="${limits.storage/(gb?GiB:MiB)}" required></div><div class="field"><label for="account-storage-unit">Unidade</label><select id="account-storage-unit" name="unit"><option value="MB" ${gb?'':'selected'}>MB</option><option value="GB" ${gb?'selected':''}>GB</option></select></div></div><button class="btn ghost" type="button" id="account-limits-default">Usar padrão: 30 MB e 1 GB</button>`,async form=>{const limits=limitsFromForm(form.get('file_mb'),form.get('storage'),form.get('unit'));const saved=await api('/admin/accounts/'+id+'/limits',{method:'PATCH',body:limits});account.limits=accountLimits(saved);if(id===state.me.profile.id)state.me.limits=account.limits;state.accounts=await api('/admin/accounts');if(state.route==='admin')render();toast('Limites da conta atualizados.');});
 $('#account-limits-default').onclick=()=>{$('#account-file-limit').value=DEFAULT_LIMITS.file/MiB;$('#account-storage-limit').value=1;$('#account-storage-unit').value='GB';$('#account-storage-limit').max='100';$('#account-storage-limit').step='1'};
 $('#account-storage-unit').onchange=e=>{const value=$('#account-storage-limit');if(e.target.value==='MB'){value.value=Number(value.value)*1024;value.max='102400'}else{value.value=Number(value.value)/1024;value.max='100'}value.step=e.target.value==='MB'?'1':'any';value.min=e.target.value==='MB'?'1':String(1/1024)};
}
