function renderAccessGate(){endSessionWork();$('.transport').hidden=true;clearPreparedAudio();const blocked=state.me?.access?.status==='blocked';state.board=null;stopAll();$('#admin-nav').hidden=true;$('#admin-library-nav').hidden=true;$('#breadcrumb').textContent='Situação da conta';$('#view').innerHTML=header(blocked?'Sua conta está bloqueada.':'Seu cadastro foi recebido.',blocked?'Fale com o administrador para revisar seu acesso.':'Aguarde a liberação do administrador para abrir seu estúdio.')+`<section class="form-panel access-card" id="account-access-gate"><div class="access-symbol" aria-hidden="true">${blocked?'⊘':'◷'}</div><div class="eyebrow">${blocked?'ACESSO BLOQUEADO':'AGUARDANDO APROVAÇÃO'}</div><h2 style="margin-top:20px">${esc(state.me.profile.display_name)}</h2><p class="fine">${esc(state.me.profile.email)}</p><p>Seu cadastro está em análise. Assim que for aprovado, seu estúdio estará disponível nesta conta.</p><div class="actions"><button class="btn primary" data-action="check-access">↻ Verificar liberação</button><button class="btn ghost" data-action="signout">Sair</button></div></section>`}
async function refreshAccess(){const previous=state.me.access?.status;const access=await api('/access');state.me.access=access;if(access.limits)state.me.limits=accountLimits(access.limits);$('#admin-nav').hidden=!access.is_admin;$('#admin-library-nav').hidden=!access.is_admin;if(access.status!=='approved'){if(previous!==access.status||!$('#account-access-gate'))renderAccessGate();return false}return true}
$('#view').addEventListener('click',async e=>{const review=e.target.closest('[data-review-id]');try{if(review){const status=review.dataset.reviewStatus;if(!confirm(status==='approved'?'Liberar o acesso desta conta?':status==='blocked'?'Bloquear o acesso desta conta?':'Voltar esta conta para pendente?'))return;review.disabled=true;try{await api('/admin/accounts/'+review.dataset.reviewId,{method:'PATCH',body:{status}});state.accounts=await api('/admin/accounts');render();toast('Situação da conta atualizada.')}finally{if(review.isConnected)review.disabled=false}}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='refresh-admin')await navigate();if(action==='check-access'){if(await refreshAccess()){state.me=await api('/me');if(!state.me.access.is_admin)void adminNotices.localUnsubscribe();updateAccount();await navigate();toast('Sua conta foi liberada.')}}}catch(error){toast(error.message,true)}});
setInterval(async()=>{if(!state.me||document.hidden)return;if(state.offline){if(navigator.onLine!==false)void verifyReconnection();return}try{const old=state.me.access?.status;if(await refreshAccess()){if(old!=='approved'){state.me=await api('/me');if(!state.me.access.is_admin)void adminNotices.localUnsubscribe();updateAccount();await navigate()}}}catch{}},30000);

let uploadLogStore=null,uploadLogOwner=null;function getUploadLog(){const owner=state.me.profile.id;if(uploadLogOwner!==owner){uploadLogOwner=owner;uploadLogStore=createUploadLog({owner})}return uploadLogStore}
function uploadLogPanel(){const log=getUploadLog();return `<section class="form-panel" style="margin-top:24px"><h2>Histórico de envios</h2>${log.durable?'':'<p class="fine">Baixe o relatório antes de sair para não perdê-lo.</p>'}${log.list().map(r=>{const c=log.summary(r);return `<details style="margin:18px 0"><summary>${esc(r.category||'Sem categoria')} · ${c.done}/${c.total} enviados · ${c.failed} falharam · ${c.pending} pendentes${r.status==='interrupted'?' · Interrompido':''}</summary><p class="fine">${esc(new Date(r.startedAt).toLocaleString('pt-BR'))}</p>${r.error?`<p>${esc(r.error)}</p>`:''}<ul>${r.files.map(f=>`<li>${esc(f.filename)} — ${f.status==='done'?'Enviado':f.status==='failed'?'Falhou':f.status==='interrupted'?'Interrompido':'Pendente'}<p class="fine">${esc(f.stage)}${f.error?' · '+esc(f.error):''}</p></li>`).join('')}</ul><button type="button" class="btn ghost" data-upload-log="${esc(r.id)}">↓ Baixar relatório</button></details>`}).join('')||'<p class="fine">Nenhum envio registrado.</p>'}</section>`}
let libraryUploadBusy=false,libraryUploadStatus='',libraryFiles=[],libraryDraft={category:'',credit:''};
function libraryFilesMarkup(){return libraryFiles.map((entry,i)=>`<div class="field"><label for="library-file-name-${i}">${esc(entry.file.name)} · ${bytes(entry.file.size)}</label><input id="library-file-name-${i}" data-library-file-index="${i}" value="${esc(entry.name)}" maxlength="120" required aria-label="Nome de ${esc(entry.file.name)}">${entry.error?`<small role="status">Falha: ${esc(entry.error)}</small>`:''}</div>`).join('')}
function adminLibraryPanel(){return header('Gerenciar biblioteca','Organize os áudios da biblioteca.','<button type="button" class="btn ghost" data-action="rename-category">Renomear categoria</button><a class="btn ghost" href="app.html#library">Ver biblioteca →</a>')+`${pendingContributionsPanel()}<form class="form-panel" id="library-upload-form"><div class="upload-diagnostics" role="alert" ${libraryFailureSummary(libraryFiles)?'':'hidden'}><strong>Motivo dos arquivos não enviados</strong><p>${esc(libraryFailureSummary(libraryFiles))}</p><p>Tente novamente os arquivos pendentes.</p></div><fieldset class="library-upload-fields" ${libraryUploadBusy?'disabled':''}><h2 style="font-size:21px">Adicionar áudios ou coletânea</h2><p class="fine">Adicione um ou mais áudios.</p><div class="field"><label for="library-category">Categoria</label><input id="library-category" name="category" maxlength="60" value="${esc(libraryDraft.category)}" placeholder="Personalizados"></div><div class="field"><label for="library-file">Arquivos de áudio</label><input id="library-file" name="file" type="file" multiple accept="audio/*,.mp3,.wav,.ogg,.m4a,.aac,.flac,.webm,.wma"><small>Máximo de 50 MB por áudio.</small></div><div id="library-file-list">${libraryFilesMarkup()}</div><div class="field"><label for="library-credit">Créditos e condições de uso</label><textarea id="library-credit" name="credit" maxlength="600" placeholder="Autor, origem e informações de uso do áudio">${esc(libraryDraft.credit)}</textarea></div><button type="submit" class="btn primary">＋ Enviar áudios</button></fieldset><p class="fine" id="library-upload-status" role="status">${esc(libraryUploadStatus)}</p></form>${uploadLogPanel()}<div class="section-title" style="margin-top:30px"><h2>${state.libraryAdmin.length} itens na biblioteca</h2></div><div class="account-list">${state.libraryAdmin.map(t=>`<article class="account-review"><div><strong>${esc(t.name)}</strong><p>${esc(libraryCategories(t).join(' · '))} · ${bytes(t.file_size)}</p></div><div class="actions"><button class="btn ghost" data-action="preview" data-id="${t.id}">▶ Ouvir</button><button class="btn ghost" data-edit-library="${t.id}">Editar</button><button class="btn danger" data-retire-sample="${t.id}">Retirar da biblioteca</button></div></article>`).join('')||'<div class="empty-state">Nenhum áudio na biblioteca.</div>'}</div>`}
