$('#view').addEventListener('submit',async e=>{
 if(e.target.id!=='library-upload-form')return;e.preventDefault();if(libraryUploadBusy)return;
 const form=e.target,data=new FormData(form);libraryDraft={category:String(data.get('category')||''),credit:String(data.get('credit')||'')};
 const batch=libraryFiles,log=getUploadLog();if(batch.length>300){toast('Selecione até 300 áudios por lote.',true);return}const report=log.start(batch,libraryDraft.category);
 try{validateLibraryFiles(batch)}catch(error){log.finish(report,error);toast(error.message,true);render();return}
 libraryUploadBusy=true;form.querySelector('fieldset').disabled=true;let outcome;
 const stage=(index,message)=>{log.stage(report,index,message);libraryUploadStatus=batch[index].name+' — '+message;const label=$('#library-upload-status');if(label)label.textContent=libraryUploadStatus};
 try{
  outcome=await uploadLibraryBatch(batch,{onProgress:(i,total)=>stage(i-1,`Preparando ${i}/${total}`),onResult:(entry,index,error,result)=>log.result(report,index,entry,error,result),upload:async entry=>{
   const index=batch.indexOf(entry);const payload=await prepareLibraryFile(entry,{onStage:message=>stage(index,message)});const params=new URLSearchParams({...libraryDraft,name:entry.name});
   return api('/admin/library?'+params,{method:'POST',body:payload,headers:{'X-File-Name':encodeURIComponent(entry.uploadFilename||entry.file.name)},onUploadStage:message=>stage(index,message)})
  }});
  log.finish(report);libraryFiles=batch.filter(entry=>entry.status!=='done');
  toast(`${outcome.done} de ${batch.length} enviados. ${outcome.failed} falharam. Consulte o histórico de envios.`,!!outcome.failed);
  try{state.libraryAdmin=await api('/admin/library');state.samples=await api('/samples')}catch{toast('Envios registrados no histórico. Não foi possível atualizar a lista da biblioteca; atualize a página.',true)}
 }catch(error){log.finish(report,error);libraryFiles=batch.filter(entry=>entry.status!=='done');toast(error.message,true)}
 finally{libraryUploadBusy=false;libraryUploadStatus='';if(state.route==='admin-library'){render();if(outcome)$('#library-upload-status').textContent=`${outcome.done} de ${batch.length} enviados, ${outcome.failed} falharam. Consulte os detalhes no histórico.`}}
});
