function renameLibraryCategory(){if(state.offline||!state.me?.access.is_admin||libraryCategoryRenameBusy)return;const names=[...new Set(state.libraryAdmin.flatMap(libraryCategories))].sort((a,b)=>a.localeCompare(b,'pt-BR'));if(!names.length){toast('Nenhuma categoria disponível para renomear.');return}modal('Renomear categoria',`<div class="field"><label for="rename-category-from">Categoria atual</label><select id="rename-category-from" name="from" required>${names.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('')}</select></div><div class="field"><label for="rename-category-to">Novo nome</label><input id="rename-category-to" name="to" maxlength="60" required placeholder="Nome da categoria"></div><p>O novo nome será aplicado aos áudios associados.</p>`,async form=>{const from=String(form.get('from')||'').trim(),to=validateLibraryCategories([String(form.get('to')||'')])[0];if(from===to)throw Error('Informe um nome diferente.');if(names.some(name=>name!==from&&name.toLocaleLowerCase('pt-BR')===to.toLocaleLowerCase('pt-BR')))throw Error('Este nome já está vinculado a outra categoria. Escolha outro.');libraryCategoryRenameBusy=true;try{const result=await api('/admin/library/categories/rename',{method:'POST',body:{from,to}});const rename=row=>({...row,category:row.category===from?to:row.category,categories:[...new Set(libraryCategories(row).map(name=>name===from?to:name))]});state.libraryAdmin=state.libraryAdmin.map(rename);state.samples=state.samples.map(rename);if(state.category===from)state.category=to;let refreshed=true;try{state.libraryAdmin=await api('/admin/library');state.samples=await api('/samples')}catch{refreshed=false}if(['library','admin-library'].includes(state.route))render();toast(refreshed?`Categoria renomeada. ${result.active_affected??0} áudios atualizados.`:'Categoria renomeada. Atualize a página para ver a mudança.')}finally{libraryCategoryRenameBusy=false}},'Renomear')}
