function editLibraryItem(id){const t=state.libraryAdmin.find(t=>t.id===id);if(!t)return;const fields=[['name','Nome',120],['author','Autor',160],['license','Licença / condições de uso',120],['source_url','Link da origem (HTTPS)',2000]];modal('Editar áudio da biblioteca',fields.map(([key,label,max])=>`<div class="field"><label for="edit-library-${key}">${label}</label><input id="edit-library-${key}" name="${key}" maxlength="${max}" value="${esc(t[key]||'')}" ${key==='source_url'?'type="url"':'required'}></div>`).join('')+`<div class="field"><label for="edit-library-categories">Categorias · uma por linha</label><textarea id="edit-library-categories" name="categories" maxlength="6100" required>${esc(libraryCategories(t).join('\n'))}</textarea></div><div class="field"><label for="edit-library-credit">Créditos e observações</label><textarea id="edit-library-credit" name="credit" maxlength="600">${esc(t.credit)}</textarea></div>`,async form=>{const values=Object.fromEntries(form);values.categories=validateLibraryCategories(String(values.categories||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean));values.category=values.categories[0];await api('/admin/library/'+id,{method:'PATCH',body:values});state.libraryAdmin=await api('/admin/library');state.samples=await api('/samples');if(state.route==='admin-library')render();toast('Dados do áudio atualizados. Os áudios nas playlists foram preservados.')})}
