const libraryInsertPending=new Set();
async function insertLibrary(id,button){const board=state.board;if(!board||button.disabled||libraryInsertPending.has(id))return;if(board.tracks.some(t=>t.sample_id===id)){button.disabled=true;button.textContent='✓ Já está na playlist';return}libraryInsertPending.add(id);button.disabled=true;let added=false;try{const track=await api('/playlists/'+board.playlist.id+'/tracks',{method:'POST',body:{sample_id:id}});board.tracks.push({...track,sample_id:id});added=true;button.textContent='✓ Já está na playlist';if(state.board===board){render();try{state.board=await api('/playlists/'+board.playlist.id);render()}catch{toast('Áudio adicionado. Atualize a playlist para recarregar os detalhes.');return}}toast('Áudio adicionado à playlist.')}finally{libraryInsertPending.delete(id);button.disabled=added||board.tracks.some(t=>t.sample_id===id)}}
let moving=false,movingPlaylists=false;
async function saveTrackOrder(ids,focusId){if(state.offline||moving||!state.board)return;const board=state.board,previous=board.tracks;const byId=new Map(previous.map(t=>[t.id,t]));if(ids.length!==previous.length||new Set(ids).size!==ids.length||ids.some(id=>!byId.has(id)))return;if(ids.every((id,i)=>id===previous[i].id))return;moving=true;board.tracks=ids.map(id=>byId.get(id));render();try{await api('/playlists/'+board.playlist.id+'/order',{method:'PATCH',body:{track_ids:ids}});if(state.board===board)toast('Ordem das faixas salva.')}catch(error){if(state.board===board){board.tracks=previous;toast('Não foi possível salvar a ordem. '+error.message,true)}}finally{moving=false;if(state.board===board){render();if(focusId)document.querySelector(`[data-track-id="${focusId}"] .pad-drag`)?.focus()}}}
attachTrackSort($('#view'),{onCommit:saveTrackOrder,isDisabled:()=>moving||!state.board||document.body.classList.contains('event-mode'),getIds:()=>state.board?.tracks.map(t=>t.id)||[]});
function displayedPlaylistIds(){if(!['dashboard','playlists','downloads'].includes(state.route))return[];if(state.offline||state.route==='downloads')return state.savedBoards.map(b=>b.playlist.id);const lists=state.overview?.playlists||[];return(state.route==='dashboard'?lists.slice(0,6):lists).map(p=>p.id)}
async function savePlaylistOrder(ids,focusId){
 if(state.offline||movingPlaylists||!state.overview)return;const overview=state.overview,owner=state.me.profile.id,version=routeVersion,previous=overview.playlists,visible=displayedPlaylistIds();if(ids.length!==visible.length||ids.some(id=>!visible.includes(id)))return;
 const all=mergePlaylistOrder(previous.map(p=>p.id),ids);if(all.every((id,i)=>id===previous[i].id))return;const byId=new Map(previous.map(p=>[p.id,p])),next=all.map((id,i)=>({...byId.get(id),position:i}));movingPlaylists=true;overview.playlists=next;render();
 try{await api('/playlists/order',{method:'PATCH',body:{playlist_ids:all}});if(state.me?.profile.id===owner){await offlinePlaylists.setOrder(owner,next).catch(()=>{});state.savedBoards=await offlinePlaylists.boards(owner).catch(()=>[]);toast('Ordem das playlists salva.')}}
 catch(error){if(state.overview===overview)overview.playlists=previous;toast('Não foi possível salvar a ordem. '+error.message,true)}
 finally{movingPlaylists=false;if(state.me?.profile.id===owner&&routeVersion===version){render();document.querySelector(`[data-playlist-id="${focusId}"] .playlist-drag`)?.focus()}}
}
attachTrackSort($('#view'),{handleSelector:'.playlist-drag',itemAttribute:'data-playlist-id',idProperty:'playlistId',onCommit:savePlaylistOrder,isDisabled:()=>state.offline||movingPlaylists||!state.overview||!['dashboard','playlists','downloads'].includes(state.route),getIds:displayedPlaylistIds});
async function eventMode(enable=!document.body.classList.contains('event-mode')){
 if(enable&&state.board?.playlist.event_fade_enabled!==false){try{await audioLevels.unlock()}catch{toast('Não foi possível preparar o fader. Tente novamente.',true);return}eventFader.setDuration(state.board.playlist.event_fade_duration??2000);eventFader.settle()}
 if(!enable&&eventFader.state())eventFader.settle();document.body.classList.toggle('event-mode',enable);void eventWake.setActive(enable);if(enable&&preview)stopPreview();updateTransport();
 if(enable){try{await document.documentElement.requestFullscreen();await screen.orientation?.lock?.('landscape')}catch{toast('Modo evento ativo. Se necessário, gire o celular na horizontal.')}}else{screen.orientation?.unlock?.();if(document.fullscreenElement)await document.exitFullscreen()}
}
