let savingDevice=false;
async function saveDevice(button){if(savingDevice||state.offline)return;const board=structuredClone(state.board),me=structuredClone(state.me),owner=me.profile.id,sessionVersion=deviceSessionVersion;if(!board?.tracks.length)return;savingDevice=true;button.disabled=true;const valid=()=>deviceSessionVersion===sessionVersion&&state.me?.profile.id===owner&&state.me?.access.status==='approved'&&!state.offline;try{
 if(!('serviceWorker' in navigator))throw Error('Este navegador não permite o modo offline.');const registration=await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('Atualize o Harmony e tente baixar novamente.')),15000))]);const worker=registration.active;if(!worker)throw Error('Feche e reabra o Harmony antes de baixar.');const shell=await new Promise(resolve=>{const channel=new MessageChannel(),timer=setTimeout(()=>resolve(false),15000);channel.port1.onmessage=e=>{clearTimeout(timer);channel.port1.close();resolve(e.data?.ready===true)};worker.postMessage({type:'HARMONY_OFFLINE_READY'},[channel.port2])});if(!shell)throw Error('Atualize o Harmony e tente baixar novamente.');
 await navigator.storage?.persist?.();const backend=await getBackend();for(let i=0;i<board.tracks.length;i++){if(!valid())throw Error('Download interrompido. Tente novamente.');const t=board.tracks[i];button.textContent=`Baixando ${i+1}/${board.tracks.length}`;if(await offlineAudio.has(owner,t.id))continue;const {saved}=await deviceAudio.get({owner,id:cacheId(t),trackId:t.id,size:t.file_size||0,url:async()=>backend.audioURL(t.id)});if(!valid())throw Error('Download interrompido.');if(!saved)throw Error('Não foi possível salvar o áudio neste dispositivo.')}
 if(!valid())throw Error('Download interrompido.');await offlinePlaylists.save(me,board);await offlinePlaylists.setOrder(owner,state.overview.playlists);state.savedBoards=await offlinePlaylists.boards(owner);if(state.board?.playlist.id===board.playlist.id)render();toast('Playlist disponível offline.');
 }catch(error){toast(error.name==='QuotaExceededError'?'Não há espaço suficiente no dispositivo. Libere espaço e tente novamente.':'Download incompleto: '+error.message,true)}finally{savingDevice=false;if(button.isConnected){button.disabled=false;button.textContent='↓ Baixar para uso offline'}}}


