function contributionsPanel(){const status={pending:'Em análise',approved:'Publicada',rejected:'Não aprovada'};return header('Minhas contribuições','Você escolhe os áudios que deseja compartilhar. A publicação depende da aprovação do administrador.','<button class="btn ghost" data-action="retry">↻ Atualizar</button>')+`<div class="account-list">${state.contributions.map(s=>`<article class="account-review"><div><strong>${esc(s.name)}</strong><p>${esc(s.author)} · ${esc(s.category)}</p><small>${esc(s.license)}</small></div><span class="pill">${status[s.status]||'Em análise'}</span></article>`).join('')||'<div class="empty-state"><h2>Compartilhe uma faixa com a comunidade.</h2><p>Abra uma playlist, edite um áudio importado por você e escolha “Enviar para a biblioteca”.</p><a class="btn primary" href="app.html#playlists">Suas playlists</a></div>'}</div>`}
