function pendingContributionsPanel(){return `<section class="contributions-panel"><div class="section-title"><h2>Contribuições para análise (${state.pendingContributions.length})</h2><button class="btn ghost small" data-action="retry">↻ Atualizar fila</button></div><p class="fine">Apenas áudios enviados voluntariamente aparecem aqui. Confira a gravação e a autorização antes de publicar.</p><div class="account-list">${state.pendingContributions.map(s=>`<article class="account-review"><div><strong>${esc(s.name)}</strong><p>${esc(s.author)} · ${esc(s.category)} · ${bytes(s.file_size)}</p><small>${esc(s.license)}${s.source_url?` · <a href="${esc(s.source_url)}" target="_blank" rel="noopener noreferrer">Origem ↗</a>`:''}</small><p>${esc(s.credit)}</p></div><div class="actions"><button class="btn ghost" data-contribution-preview="${s.id}" ${s.preview_url?'':'disabled'}>▶ Ouvir</button><button class="btn primary" data-contribution-review="${s.id}">Revisar e publicar</button><button class="btn danger" data-contribution-reject="${s.id}">Recusar</button></div></article>`).join('')||'<p class="fine">Nenhuma contribuição pendente.</p>'}</div></section>`}
