function adminNotificationPanel(){
 const status=notificationState.status,enabled=status==='enabled';
 const messages={loading:'Carregando…',enabled:'Ativas neste aparelho.',disabled:'Receba avisos de novos cadastros neste aparelho.',blocked:'Permita as notificações nas configurações do navegador.',unsupported:'Instale o Harmony e abra pelo ícone para ativar as notificações.',error:'Não foi possível consultar. Tente novamente.'};
 const disabled=notificationBusy||['loading','unsupported','blocked'].includes(status);
 return `<section id="admin-notifications" class="form-panel" style="margin-bottom:24px"><h2>Notificações de cadastro</h2><p class="fine" role="status">${messages[status]||messages.disabled}</p><div class="actions"><button type="button" class="btn ${enabled?'ghost':'primary'}" data-notification-action="${enabled?'disable':'enable'}" ${disabled?'disabled':''}>${notificationBusy?'Aguarde…':enabled?'Desativar neste aparelho':'Ativar notificações'}</button>${enabled?`<button type="button" class="btn ghost" data-notification-action="test" ${notificationBusy?'disabled':''}>Testar notificação</button>`:''}${['error','blocked'].includes(status)?'<button type="button" class="btn ghost" data-notification-action="refresh">Verificar novamente</button>':''}</div></section>`;
}
function updateNotificationPanel(){const panel=$('#admin-notifications');if(panel&&state.me?.access?.is_admin)panel.outerHTML=adminNotificationPanel()}
async function refreshAdminNotifications(){const version=++notificationVersion;try{const result=await adminNotices.status();if(version===notificationVersion)notificationState=result}catch{if(version===notificationVersion)notificationState={status:'error'}}if(version===notificationVersion)updateNotificationPanel()}
$('#view').addEventListener('click',async event=>{
 const button=event.target.closest('[data-notification-action]');if(!button||notificationBusy||!state.me?.access?.is_admin)return;
 const action=button.dataset.notificationAction;notificationBusy=true;++notificationVersion;updateNotificationPanel();
 try{if(action==='enable')notificationState=await adminNotices.enable();if(action==='disable')notificationState=await adminNotices.disable();if(action==='refresh')notificationState=await adminNotices.status();if(action==='test'){await adminNotices.test();toast('Notificação de teste solicitada.')}}
 catch(error){if(window.Notification?.permission==='denied')notificationState={status:'blocked'};toast(error.message,true)}
 finally{notificationBusy=false;updateNotificationPanel()}
});
navigator.serviceWorker?.addEventListener('message',event=>{if(event.source?.scriptURL===new URL('./sw.js',location.href).href&&event.data?.type==='HARMONY_OPEN_ADMIN'){if(location.hash==='#admin')void navigate();else location.hash='admin'}});


function deleteAccountDialog(id){
 const account=state.accounts.find(a=>a.user_id===id);if(!account||!account.can_delete||account.is_admin||id===state.me.profile.id)return;
 const submit=account.deletion_status?'Concluir exclusão':'Excluir conta';
 modal('Excluir conta',`<p><strong>${esc(account.display_name||account.email)}</strong><br>${esc(account.email)}</p><p>A conta, as playlists e os arquivos pessoais serão excluídos. Esta ação não pode ser desfeita.</p><p class="fine">Áudios publicados na biblioteca e cópias já importadas por outros membros serão mantidos.</p><div class="field"><label for="delete-account-email">Digite o e-mail da conta para confirmar</label><input id="delete-account-email" name="confirmation_email" type="email" required maxlength="254" autocomplete="off" autocapitalize="none" spellcheck="false"></div>`,async form=>{
  const confirmation=String(form.get('confirmation_email')||'').trim().toLowerCase();if(confirmation!==account.email.toLowerCase())throw Error('Digite o e-mail da conta para confirmar.');
  accountDeletionBusy=true;$('#modal-cancel').disabled=true;$('#modal-submit').textContent='Excluindo…';
  try{await api('/admin/accounts/'+encodeURIComponent(id),{method:'DELETE',body:{confirmation_email:confirmation}});state.accounts=state.accounts.filter(a=>a.user_id!==id);if(state.route==='admin')render();toast('Conta excluída.');}
  catch(error){try{state.accounts=await api('/admin/accounts');if(state.route==='admin')render()}catch{}throw error}
  finally{accountDeletionBusy=false;$('#modal-cancel').disabled=false;$('#modal-submit').textContent=submit}
 },submit);
 $('#modal-submit').className='btn danger';
}
$('#view').addEventListener('click',event=>{const button=event.target.closest('[data-delete-account]');if(button&&!accountDeletionBusy&&state.me?.access?.is_admin)deleteAccountDialog(button.dataset.deleteAccount)});

document.addEventListener('click',()=>{if(document.body.classList.contains('event-mode')&&['released','blocked'].includes(eventWake.state()))void eventWake.ensure()});
